/*
 * prog24_query_string_parser – reproduced from the original binary
 *
 * Behaviour:
 *   * reads one line from stdin (max 2048 bytes, including the trailing '\n')
 *   * if nothing is read → prints "NO_INPUT" and exits
 *   * otherwise parses the line as a URL query string:
 *         key=value&key2=value2&...
 *     – keys and values are URL‑decoded:
 *         '+'  → space
 *         "%XY" where X and Y are hexadecimal digits → the byte with value 0xXY
 *       (invalid % sequences are copied verbatim)
 *   * for each pair prints "key=value" followed by a newline.
 *
 * The implementation follows the logic of the original binary but is written
 * in clear C without any of the obfuscation.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_LINE 2048          /* matches the original 0x800 buffer */
#define MAX_DECODED 2048       /* decoded key/value will never be longer */

/* ---------------------------------------------------------------------
 * URL‑decode a string.
 *   src   – pointer to the source string
 *   len   – number of bytes to read from src
 *   dest  – buffer where the decoded string is written; must be large enough
 * Returns the length of the decoded string (excluding the terminating NUL).
 * The decoder implements the same rules as the original binary:
 *   '+'  → space
 *   "%XY" where X and Y are hex digits → the byte 0xXY
 *   any other character → copied unchanged
 *   malformed % sequences are copied unchanged.
 * --------------------------------------------------------------------- */
static size_t url_decode(const char *src, size_t len, char *dest)
{
    size_t i = 0, o = 0;
    while (i < len) {
        char c = src[i];
        if (c == '+') {
            dest[o++] = ' ';
            i++;
        } else if (c == '%' && i + 2 < len &&
                   isxdigit((unsigned char)src[i + 1]) &&
                   isxdigit((unsigned char)src[i + 2])) {
            char hi = src[i + 1];
            char lo = src[i + 2];
            int hi_val = isdigit((unsigned char)hi) ? hi - '0' : (tolower((unsigned char)hi) - 'a' + 10);
            int lo_val = isdigit((unsigned char)lo) ? lo - '0' : (tolower((unsigned char)lo) - 'a' + 10);
            dest[o++] = (char)(hi_val * 16 + lo_val);
            i += 3;
        } else {
            dest[o++] = c;
            i++;
        }
    }
    dest[o] = '\0';
    return o;
}

int main(void)
{
    static char line[MAX_LINE];
    static char key[MAX_DECODED];
    static char val[MAX_DECODED];

    if (fgets(line, sizeof(line), stdin) == NULL) {
        puts("NO_INPUT");
        return 0;
    }

    /* Strip trailing newline and optional carriage return */
    size_t linelen = strlen(line);
    while (linelen > 0 && (line[linelen - 1] == '\n' || line[linelen - 1] == '\r')) {
        line[--linelen] = '\0';
    }

    size_t pos = 0;  /* current position in the line */
    while (pos < linelen) {
        /* Find the next '&' or end of string */
        size_t amp = pos;
        while (amp < linelen && line[amp] != '&')
            amp++;

        /* Find the first '=' within this segment */
        size_t eq = pos;
        while (eq < amp && line[eq] != '=')
            eq++;

        /* Decode key */
        url_decode(line + pos, eq - pos, key);

        /* Decode value if there is an '=' */
        if (eq < amp) {
            url_decode(line + eq + 1, amp - eq - 1, val);
        } else {
            val[0] = '\0';
        }

        printf("%s=%s\n", key, val);

        /* Move past the '&' (or to the end) */
        pos = amp + 1;
    }

    return 0;
}
